const icons={bell:'<path d="M6 9a6 6 0 0 1 12 0c0 7 3 7 3 8H3c0-1 3-1 3-8Z"/><path d="M10 21h4"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',home:'<path d="m3 10 9-7 9 7v11H3V10Z"/><path d="M9 21v-8h6v8"/>',heart:'<path d="M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-5 4 0 10 8 16 8-6 13-12 8-16Z"/>',orders:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h4"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="currentColor"/><circle cx="15" cy="17" r="2" fill="currentColor"/>',back:'<path d="m12 5-7 7 7 7M5 12h15"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const svg=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.bag}</svg>`;
function foodImage(item){if(item.imageUrl)return item.imageUrl;if(item.image)return '/assets/'+item.image+'-cutout.webp';return 'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="240" height="180"><circle cx="120" cy="90" r="56" fill="#eeefe7"/><circle cx="120" cy="90" r="40" fill="none" stroke="#cdd1c3" stroke-width="3"/></svg>');}
let dishes=[{id:'plov',name:'Плов',price:450,weight:'450 г',category:'Горячее',image:'plov',desc:'Классика нашего меню. Состав блюда уточняется перед запуском.'},{id:'kazan',name:'Казан-кебаб из говядины',price:550,weight:'400 г',category:'Горячее',image:'kazan',desc:'Говядина с картофелем. Полный состав уточняется перед запуском.'},{id:'shurpa',name:'Шурпа из говядины',price:400,weight:'450 г',category:'Супы',image:'shurpa',desc:'Порция 450 г, мясо 120 г. Полный состав уточняется.'},{id:'roast',name:'Жаркое из говядины',price:500,weight:'450 г',category:'Горячее',image:'roast',desc:'Горячее блюдо из говядины. Полный состав уточняется.'},{id:'fatir',name:'Фатир-шурпа',price:500,weight:'600 г',category:'Супы',image:'fatir',desc:'Большая порция любимого супа. Полный состав уточняется.'},{id:'lamb',name:'Казан-кебаб из баранины',price:600,weight:'400 г',category:'Горячее',desc:'Баранина с картофелем. Полный состав уточняется.'}];
let products=[];
const allItems=()=>[...dishes,...products];
const defaultBanners=[
{id:'family',eyebrow:'Вкусно вместе',title:'Семейный обед',text:'Любимые блюда для всей семьи',badge:'от 450 ₽',image:'plov',tone:'orange'},
{id:'hot',eyebrow:'Горячее меню',title:'С пылу с жару',text:'Сытные блюда из мяса и картофеля',badge:'Попробуйте',image:'kazan',tone:'charcoal'},
{id:'soup',eyebrow:'Каждый день',title:'Домашние супы',text:'Согревающий вкус и щедрые порции',badge:'от 400 ₽',image:'shurpa',tone:'cream'}
];
let promoIndex=0,promoController=null;
const state={page:'menu',category:'Все',mode:'Кафе',query:'',cart:{},favorites:[],branch:false,fulfillment:'Доставка'};
try{const v=JSON.parse(localStorage.getItem('sof-prototype')||'{}');state.cart=v.cart||{};state.favorites=v.favorites||[]}catch{}
const money=v=>new Intl.NumberFormat('ru-RU').format(v)+' ₽';const qty=id=>state.cart[id]||0;const total=()=>allItems().reduce((s,p)=>s+p.price*qty(p.id),0);const count=()=>Object.values(state.cart).reduce((a,b)=>a+b,0);const safe=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=svg(e.dataset.icon))}function persist(){localStorage.setItem('sof-prototype',JSON.stringify({cart:state.cart,favorites:state.favorites}))}function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2800)}
function change(id,delta){const dish=allItems().find(d=>d.id===id);if(!dish||delta>0&&dish.available===false){toast('Позиция сейчас недоступна');return}if(delta>0&&dish.stock!=null&&qty(id)+delta>dish.stock){toast('Указанный остаток меньше выбранного количества');return}state.cart[id]=Math.max(0,qty(id)+delta);if(!qty(id))delete state.cart[id];persist();render();if(document.querySelector('#productDialog').open)showProduct(id)}
function favorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render()}
function counter(p){if(p.available===false)return '<span class="sold-out">Нет в наличии</span>';return `<div class="qty">${qty(p.id)?`<button data-delta="-1" data-id="${p.id}" aria-label="Убрать одну единицу">−</button><span>${qty(p.id)}</span>`:''}<button class="plus" data-delta="1" data-id="${p.id}" aria-label="Добавить ${safe(p.name)}">+</button></div>`}
function originalCard(p){return `<article class="food"><button class="heart ${state.favorites.includes(p.id)?'on':''}" data-favorite="${p.id}" aria-label="В избранное" aria-pressed="${state.favorites.includes(p.id)}">${svg('heart')}</button><div class="photo" data-product="${p.id}" role="button" tabindex="0" aria-label="Подробнее: ${safe(p.name)}"><img src="${foodImage(p)}" alt="${safe(p.name)}" loading="lazy"></div><h3 data-product="${p.id}">${safe(p.name)}</h3><p class="weight">${safe(p.weight)}</p><div class="price-row"><span class="price">${p.price}<em>₽</em></span>${counter(p)}</div></article>`}
function pageHead(title){return `<div class="page-head"><button class="circle" data-page="menu" aria-label="Назад к меню">${svg('back')}</button><h1>${title}</h1><span style="width:39px"></span></div>`}
function originalMenu(){let filtered=dishes.filter(p=>(state.category==='Все'||p.category===state.category)&&p.name.toLowerCase().includes(state.query.toLowerCase()));return `<h1 class="intro">Голодны? <span>Вам в «Соф».</span></h1><div class="modes"><button data-mode="Кафе" class="${state.mode==='Кафе'?'active':''}">Кафе</button><button data-mode="Продукты" class="${state.mode==='Продукты'?'active':''}">Продукты</button></div>${state.mode==='Продукты'?'<div class="empty-shop"><span class="muted">СОФ · МАГАЗИН</span><h2>Всё для<br>вкусного дома.</h2><p>Здесь появится каталог продуктов.<br>Ассортимент и цены добавим перед запуском.</p><button class="primary" data-mode="Кафе">Посмотреть меню кафе</button></div>':`<div class="search"><label>${svg('search')}<input id="search" placeholder="Найти любимое блюдо" value="${safe(state.query)}" aria-label="Поиск блюд"></label><button class="circle" id="filterButton" aria-label="Показать все блюда">${svg('filter')}</button></div><div class="categories">${[['Все','plov'],['Горячее','kazan'],['Супы','shurpa']].map(([name,img])=>`<button class="category ${state.category===name?'active':''}" data-category="${name}"><img src="assets/${img}.png" alt="">${name}</button>`).join('')}</div><div class="section-title"><h2>${state.query?'Результаты поиска':state.category==='Все'?'Выбирайте любимое':state.category}</h2><small>${filtered.length} блюд</small></div><div class="grid">${filtered.map(card).join('')||'<p class="no-results">Блюдо не найдено. Попробуйте другое название.</p>'}</div><p class="subtle">Часть меню для демонстрации интерфейса.<br>Фото из макета меню; подачу подтвердим перед запуском.</p>`}`}
function summary(){return `<div class="summary-row"><span>Позиции · ${count()}</span><span>${money(total())}</span></div><div class="summary-row"><span>Доставка</span><span>Уточняется</span></div><div class="summary-row total"><span>Сумма позиций</span><span>${money(total())}</span></div>`}
function cart(){return pageHead('Ваша корзина')+(count()?`<div class="cart-list">${allItems().filter(p=>qty(p.id)).map(p=>`<article class="cart-item"><img src="${foodImage(p)}" alt="${safe(p.name)}"><div class="cart-details"><h3>${safe(p.name)}</h3><small>${safe(p.weight)}</small><div class="price-row"><span class="price">${money(p.price*qty(p.id))}</span>${counter(p)}</div></div></article>`).join('')}</div><div class="panel"><h2>Ваш заказ</h2>${summary()}<button class="primary" data-page="checkout">К оформлению →</button></div><p class="subtle">Стоимость доставки будет определена после настройки зон.</p>`:empty('bag','Пока пусто','Добавьте что-нибудь вкусное из меню.'))}
function empty(icon,title,desc){return `<div class="empty"><span class="icon-box">${svg(icon)}</span><h2>${title}</h2><p>${desc}</p><button class="primary" data-page="menu">Открыть меню</button></div>`}
function checkout(){if(!count())return cart();return pageHead('Оформление')+`<form id="checkoutForm"><div class="panel" style="margin-top:0"><h2>Как получить заказ?</h2>${['Доставка','Самовывоз','За столом'].map(x=>`<label class="radio"><input type="radio" name="fulfillment" value="${x}" ${x===state.fulfillment?'checked':''}>${x}</label>`).join('')}</div><div class="panel"><h2>Контактные данные</h2><label class="field">Ваше имя<input name="name" autocomplete="given-name" required placeholder="Как к вам обращаться?"></label><label class="field">Телефон<input name="phone" type="tel" autocomplete="tel" required minlength="10" placeholder="+7 (___) ___-__-__"></label><label class="field" id="addressField">${state.fulfillment==='За столом'?'Номер стола':state.fulfillment==='Самовывоз'?'Филиал самовывоза':'Адрес доставки'}<input name="address" required placeholder="${state.fulfillment==='За столом'?'Например, 5':state.fulfillment==='Самовывоз'?'Выберите филиал перед запуском':'Улица, дом, квартира'}"></label><label class="field">Комментарий<textarea name="comment" placeholder="Пожелания к заказу"></textarea></label></div><div class="panel"><h2>Способ оплаты</h2><label class="radio"><input type="radio" name="payment" checked value="cash"><span class="payment">₽</span>Наличными при получении</label><label class="radio"><input type="radio" name="payment" value="card"><span class="payment">▰</span>Картой при получении</label><p class="muted" style="font-size:10px">Способы оплаты демонстрационные. Онлайн-оплату подключим отдельно.</p></div><div class="panel"><h2>Итого</h2>${summary()}<button class="primary" type="submit">Проверить оформление · ${money(total())}</button></div><p class="subtle">Демонстрационный режим. Заказ и контактные данные<br>никуда не отправляются и не сохраняются.</p></form>`}
const preferences={sound:true,haptics:true};
let localProfile={name:'',email:'',address:''};
try{Object.assign(preferences,JSON.parse(localStorage.getItem('sof-feedback')||'{}'));Object.assign(localProfile,JSON.parse(localStorage.getItem('sof-local-profile')||'{}'))}catch{}
function profile(){return pageHead('Мой профиль')+`<div class="profile-title"><div class="profile-icon">${svg('user')}</div><h2>${safe(localProfile.name)||'Рады видеть вас в «Соф»'}</h2><p>Войдите, чтобы ваши заказы всегда были рядом</p><span class="guest-chip">Гостевой профиль</span></div><div class="panel login-panel"><h2>Войти или зарегистрироваться</h2><button class="auth-button yandex" data-auth="yandex"><b>Я</b>Войти с Яндекс ID<span>→</span></button><button class="auth-button phone" data-auth="phone">${svg('user')}По номеру телефона<span>→</span></button><button class="auth-button max" data-auth="max"><b>М</b>Продолжить в MAX<span>→</span></button><p class="auth-note">Способы входа готовятся к подключению</p></div><div class="profile-shortcuts"><button data-page="orders">${svg('orders')}<strong>Заказы</strong><small>История заказов</small></button><button data-page="favorites">${svg('heart')}<strong>Избранное</strong><small>${state.favorites.length} сохранено</small></button></div><div class="panel"><h2>Личное</h2><button class="menu-row" data-profile="details">${svg('user')}Мои данные<span>→</span></button><button class="menu-row" data-profile="address">${svg('pin')}Адрес доставки<span>→</span></button><button class="menu-row" id="profileBranch">${svg('pin')}Мой филиал<span>${state.branch?'Выбран':'Выбрать'} →</span></button></div><div class="panel"><h2>Настройки приложения</h2>${[['sound','Звук переключения','Мягкий щелчок при выборе категории'],['haptics','Вибрация','Если поддерживается устройством']].map(([key,label,desc])=>`<button class="setting-row" data-setting="${key}" role="switch" aria-checked="${preferences[key]}"><span><strong>${label}</strong><small>${desc}</small></span><i class="toggle ${preferences[key]?'on':''}"></i></button>`).join('')}</div><div class="panel"><button class="menu-row" data-profile="help">${svg('bell')}Помощь и информация<span>→</span></button></div><p class="subtle">Соф · С заботой о каждом заказе<br>Демонстрационная версия</p>`}
function openAccountSheet(kind){const d=document.querySelector('#accountDialog');const head=t=>`<div class="sheet-head"><h2>${t}</h2><button class="circle" onclick="this.closest('dialog').close()" aria-label="Закрыть">✕</button></div>`;
if(kind==='details'||kind==='address'){d.innerHTML=head(kind==='details'?'Мои данные':'Адрес доставки')+`<p class="muted">Сохраняется только в этом браузере до подключения личного кабинета.</p><form id="localProfileForm" data-kind="${kind}">${kind==='details'?`<label class="field">Имя<input name="name" maxlength="60" autocomplete="given-name" value="${safe(localProfile.name)}" required></label><label class="field">Электронная почта<input name="email" type="email" autocomplete="email" value="${safe(localProfile.email)}"></label>`:`<label class="field">Адрес<input name="address" maxlength="250" autocomplete="street-address" value="${safe(localProfile.address)}" placeholder="Улица, дом, квартира" required></label>`}<button class="primary" type="submit">Сохранить</button></form>`}
else if(kind==='phone'){d.innerHTML=head('Вход по телефону')+`<p class="muted">Ваш номер — для входа и связи по заказу.</p><form id="phoneAuthForm"><label class="field">Номер телефона<input name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+7 (999) 123-45-67" required pattern="[+0-9 ()-]{10,20}"></label><div class="connection-note">SMS-вход ещё не подключён. Код пока не отправляется.</div><button class="primary" type="submit">Проверить подключение SMS</button></form>`}
else if(kind==='yandex'||kind==='max'){d.innerHTML=head(kind==='yandex'?'Вход с Яндекс ID':'Вход через MAX')+`<div class="provider-hero ${kind}">${kind==='yandex'?'Я':'М'}</div><h3>Скоро можно будет войти</h3><p class="muted">${kind==='yandex'?'После подключения Яндекс ID вы сможете безопасно войти через свой аккаунт.':'После подключения мини-приложения «Соф» в MAX здесь появится вход через ваш аккаунт.'}</p><div class="connection-note">Этот способ входа ещё не подключён.</div><button class="primary" onclick="this.closest('dialog').close()">Понятно</button>`}
else{d.innerHTML=head('Помощь и информация')+`<p class="muted">Это демонстрационная версия «Соф». Реальные заказы, оплата и вход ещё не подключены.</p><p class="muted">Контакты ресторана, правила доставки и документы появятся перед запуском.</p><button class="primary" onclick="this.closest('dialog').close()">Понятно</button>`}d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.auth)openAccountSheet(b.dataset.auth);if(b.dataset.profile)openAccountSheet(b.dataset.profile);if(b.dataset.setting){unlockFeedback();const key=b.dataset.setting;preferences[key]=!preferences[key];localStorage.setItem('sof-feedback',JSON.stringify(preferences));render();if(preferences[key])selectionFeedback()}});
document.addEventListener('submit',e=>{if(e.target.id==='localProfileForm'){e.preventDefault();for(const key of ['name','email','address']){const input=e.target.querySelector(`[name="${key}"]`);if(input)localProfile[key]=input.value.trim()}localStorage.setItem('sof-local-profile',JSON.stringify(localProfile));document.querySelector('#accountDialog').close();render();toast('Сохранено на этом устройстве')}if(e.target.id==='phoneAuthForm'){e.preventDefault();toast('SMS-вход ещё не подключён. Код не отправлен.')}});
function render(){document.querySelector('#view').innerHTML=state.page==='menu'?menu():state.page==='cart'?cart():state.page==='checkout'?checkout():state.page==='favorites'?pageHead('Избранное')+(state.favorites.length?`<div class="grid">${allItems().filter(p=>state.favorites.includes(p.id)).map(card).join('')}</div>`:empty('heart','Любимое — рядом','Нажмите на сердечко у понравившегося блюда.')):state.page==='orders'?pageHead('Мои заказы')+empty('orders','Пока нет заказов','После подключения сервиса здесь появится история.'):state.page==='success'?`<div class="success"><div class="icon-box">${svg('check')}</div><h2>Оформление проверено</h2><p>Это демонстрация оформления.<br>Это тест: ресторан заказ не получил,<br>оплата не списывалась.</p><button class="primary" data-page="menu">Вернуться в меню</button></div>`:profile();document.querySelector('#nav').innerHTML=`<div class="bottom-nav">${[['menu','home','Меню'],['favorites','heart','Избранное'],['orders','orders','Заказы'],['cart','bag','Корзина'],['profile','user','Профиль']].map(([p,icon,label])=>`<button data-page="${p}" aria-label="${label}" ${state.page===p?'aria-current="page"':''} class="${state.page===p?'active':''}">${svg(icon)}${p==='cart'&&count()?`<span class="nav-count">${count()}</span>`:''}</button>`).join('')}</div>${count()&&['menu','favorites'].includes(state.page)?`<button class="cart-floating" data-page="cart"><small>В корзине · ${count()} шт.</small><strong>${money(total())}</strong><span class="round">${svg('bag')}</span></button>`:''}`;const b=document.querySelector('#cartBadge');b.hidden=!count();b.textContent=count();hydrate()}
function navigate(p){state.page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function showProduct(id){const p=allItems().find(p=>p.id===id);if(!p)return;const d=document.querySelector('#productDialog');d.innerHTML=`<div class="sheet-head"><small class="muted">${safe(p.category)}</small><button class="circle" aria-label="Закрыть" onclick="this.closest('dialog').close()">✕</button></div><img class="detail-photo" src="${foodImage(p)}" alt="${safe(p.name)}"><h2 class="detail-name">${safe(p.name)}</h2><span class="detail-weight">${safe(p.weight)}</span><p class="detail-desc">${safe(p.desc)}</p><div class="price-row"><span class="price">${money(p.price)}</span>${counter(p)}</div><button class="primary" onclick="this.closest('dialog').close()">Вернуться к меню</button>`;if(!d.open)d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-product]');if(!b||b.disabled)return;if(b.dataset.delta)change(b.dataset.id,Number(b.dataset.delta));else if(b.dataset.favorite)favorite(b.dataset.favorite);else if(b.dataset.product)showProduct(b.dataset.product);else if(b.dataset.page)navigate(b.dataset.page);else if(b.dataset.category){selectArcCategory(b)}else if(b.dataset.mode){state.mode=b.dataset.mode;state.category='Все';state.query='';updateCatalogCategories();render()}else if(['branchButton','profileBranch'].includes(b.id))openBranchSelector();else if(b.id==='headerCart')navigate('cart');else if(b.id==='filterButton'){state.category='Все';state.query='';render();toast('Показаны все блюда')}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.product)showProduct(e.target.dataset.product)});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;state.query=e.target.value;render();const s=document.querySelector('#search');s.focus();s.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.name==='fulfillment'){state.fulfillment=e.target.value;const values=Object.fromEntries(new FormData(document.querySelector('#checkoutForm')));render();const f=document.querySelector('#checkoutForm');for(const [k,v]of Object.entries(values)){const input=f.querySelector(`[name="${k}"]:not([type="radio"])`);if(input&&k!=='address')input.value=v}}});
document.addEventListener('submit',e=>{if(e.target.id==='checkoutForm'){e.preventDefault();navigate('success')}});

let arcCategories=[{name:'Горячее',image:'kazan'},{name:'Говядина',image:'roast'},{name:'Все',image:'plov'},{name:'Супы',image:'shurpa'},{name:'Баранина',image:'kazan'}];
function visibleItems(){return state.mode==='Продукты'?products:dishes}
function matchesCategory(p){return state.category==='Все'||p.category===state.category||(state.category==='Говядина'&&p.name.includes('говядины'))||(state.category==='Баранина'&&p.name.includes('баранины'))}
function card(p){return `<article class="food"><div class="photo" data-product="${p.id}" role="button" tabindex="0" aria-label="Подробнее: ${safe(p.name)}"><img src="${foodImage(p)}" alt="${safe(p.name)}" loading="lazy"></div><div class="food-copy"><span class="dish-label">${safe(p.category.toUpperCase())}</span><h3 data-product="${p.id}">${safe(p.name)}</h3><p class="weight">${safe(p.weight)}</p><div class="price-row"><span class="price"><em>₽</em>${p.price}</span>${counter(p)}</div></div></article>`}
function menu(){const filtered=visibleItems().filter(p=>matchesCategory(p)&&p.name.toLowerCase().includes(state.query.toLowerCase()));return `<h1 class="intro">Голодны? <span>Закажите в «Соф».</span></h1>${products.length?`<div class="modes"><button data-mode="Кафе" class="${state.mode==='Кафе'?'active':''}">Кафе</button><button data-mode="Продукты" class="${state.mode==='Продукты'?'active':''}">Продукты</button></div>`:''}<div class="search"><label>${svg('search')}<input id="search" placeholder="Найти любимое блюдо..." value="${safe(state.query)}" aria-label="Поиск блюд"></label><button class="circle" id="filterButton" aria-label="Показать все блюда">${svg('filter')}</button></div>${promoMarkup()}<div class="arc-shell"><div class="arc-backdrop"></div><div class="arc-track" id="arcTrack" role="tablist" aria-label="Категории блюд">${arcCategories.map((c,i)=>`<button class="arc-category ${state.category===c.name?'active':''}" data-category="${safe(c.name)}" data-slot="${i}" role="tab" aria-selected="${state.category===c.name}" tabindex="${state.category===c.name?'0':'-1'}"><img src="${foodImage(c)}" alt=""><span>${safe(c.name)}</span><b></b></button>`).join('')}</div></div><div class="grid" id="menuGrid">${filtered.map(card).join('')||'<p class="no-results">Позиции не найдены. Попробуйте другую категорию или название.</p>'}</div><p class="subtle">Соф · Каталог<br>Заказы и оплата не подключены</p>`}
function getPromoBanners(){
  const configured=typeof cafeSettings!=='undefined'&&Array.isArray(cafeSettings?.banners)?cafeSettings.banners.filter(b=>b&&b.enabled!==false):[];
  return configured.length?configured:defaultBanners;
}
function promoMarkup(){
  const banners=getPromoBanners();
  return `<section class="sof-banner" aria-label="Акции и предложения"><div class="sof-banner-track" id="promoTrack">${banners.map((b,i)=>`<article class="sof-banner-slide tone-${safe(String(b.tone||defaultBanners[i%defaultBanners.length].tone))}" data-promo-slide="${i}"><div class="sof-banner-copy"><small>${safe(String(b.eyebrow||'Специальное предложение'))}</small><h2>${safe(String(b.title||'Любимые блюда'))}</h2><p>${safe(String(b.text||b.subtitle||'Закажите в «Соф»'))}</p><strong>${safe(String(b.badge||'Попробуйте'))}</strong></div><img src="${safe(String(b.imageUrl||foodImage({image:b.image||defaultBanners[i%defaultBanners.length].image})))}" alt="" loading="${i?'lazy':'eager'}"></article>`).join('')}</div><div class="sof-banner-dots" role="tablist" aria-label="Выбор баннера">${banners.map((_,i)=>`<button type="button" data-promo-index="${i}" class="${i===promoIndex?'active':''}" aria-label="Баннер ${i+1}" aria-selected="${i===promoIndex}"></button>`).join('')}</div></section>`;
}
function attachPromo(){
  promoController?.destroy();promoController=null;
  const track=document.querySelector('#promoTrack');if(!track)return;
  const slides=[...track.querySelectorAll('[data-promo-slide]')],dots=[...document.querySelectorAll('[data-promo-index]')];
  if(!slides.length)return;promoIndex=Math.min(promoIndex,slides.length-1);
  let timer=0,scrollFrame=0,paused=false;
  const select=index=>{promoIndex=wrapIndex(index,slides.length);dots.forEach((dot,i)=>{const active=i===promoIndex;dot.classList.toggle('active',active);dot.setAttribute('aria-selected',String(active))})};
  const go=(index,behavior='smooth')=>{select(index);track.scrollTo({left:slides[promoIndex].offsetLeft,behavior})};
  const start=()=>{clearInterval(timer);if(slides.length>1&&!paused&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>go(promoIndex+1),4800)};
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>{go(i);start()}));
  track.addEventListener('scroll',()=>{cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(()=>{const index=Math.round(track.scrollLeft/Math.max(1,track.clientWidth));select(index)})},{passive:true});
  track.addEventListener('pointerdown',()=>{paused=true;clearInterval(timer)});
  track.addEventListener('pointerup',()=>{paused=false;start()});
  track.addEventListener('pointercancel',()=>{paused=false;start()});
  requestAnimationFrame(()=>go(promoIndex,'auto'));start();
  promoController={destroy(){clearInterval(timer);cancelAnimationFrame(scrollFrame)}};
}

let arcController=null,audioContext=null;
function unlockFeedback(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!audioContext&&Audio)audioContext=new Audio();if(audioContext?.state==='suspended')audioContext.resume().catch(()=>{})}catch{}}
function selectionFeedback(){if(preferences.haptics){try{window.navigator?.vibrate?.(8)}catch{}}if(preferences.sound&&audioContext?.state==='running'){try{const t=audioContext.currentTime,o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(1200,t);o.frequency.exponentialRampToValueAtTime(650,t+.018);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.045,t+.002);g.gain.exponentialRampToValueAtTime(.0001,t+.028);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.03)}catch{}}}
function wrapIndex(v,n){return ((v%n)+n)%n}
function circularPosition(offset,radius,step){const angle=offset*step;return {x:radius*Math.sin(angle),y:radius*(1-Math.cos(angle))}}
function attachArc(){arcController?.destroy();arcController=null;const track=document.querySelector('#arcTrack');if(!track)return;const buttons=[...track.querySelectorAll('.arc-category')],n=buttons.length;let position=arcCategories.findIndex(c=>c.name===state.category);if(position<0)position=2;let target=position,frame=0,timer=0,drag=null,ignoreClick=false;const step=.115;
function paint(){const radius=track.clientWidth*1.35;track.parentElement.style.setProperty('--ring-radius',radius+'px');buttons.forEach((el,i)=>{const offset=wrapIndex(i-position+n/2,n)-n/2;const p=circularPosition(offset,radius,step);el.style.transform=`translate(-50%,0) translate(${p.x}px,${p.y}px)`;el.style.opacity=Math.abs(offset)>2.2?'0':'1';el.style.zIndex=String(10-Math.round(Math.abs(offset)*2))})}
function choose(){const selected=arcCategories[wrapIndex(Math.round(position),n)].name;if(state.category!==selected){state.category=selected;updateArcSelection(track);updateMenuGrid();selectionFeedback()}}
function animate(){frame=0;if(!track.isConnected)return;const delta=target-position;position=Math.abs(delta)<.002?target:position+delta*.2;paint();choose();if(position!==target)frame=requestAnimationFrame(animate)}
function move(v){target=v;if(matchMedia('(prefers-reduced-motion: reduce)').matches){position=target;paint();choose()}else if(!frame)frame=requestAnimationFrame(animate)}
track.addEventListener('pointerdown',e=>{if(e.button!==0)return;unlockFeedback();cancelAnimationFrame(frame);frame=0;target=position;drag={x:e.clientX,y:e.clientY,start:position,moved:false,id:e.pointerId};ignoreClick=false});
track.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x;if(!drag.moved&&Math.abs(e.clientY-drag.y)>Math.abs(dx)+8){drag=null;return}if(Math.abs(dx)>5){drag.moved=true;track.setPointerCapture?.(e.pointerId)}if(drag.moved){position=drag.start-dx/(track.clientWidth*1.35*step);target=position;paint();choose()}});
function endDrag(e){if(!drag||e.pointerId!==drag.id)return;ignoreClick=drag.moved;drag=null;move(Math.round(position))}
track.addEventListener('pointerup',endDrag);track.addEventListener('pointercancel',endDrag);track.addEventListener('click',e=>{if(ignoreClick){e.preventDefault();e.stopPropagation();ignoreClick=false}},{capture:true});
track.addEventListener('wheel',e=>{e.preventDefault();unlockFeedback();move(target+Math.max(-.6,Math.min(.6,(Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY)/100)));clearTimeout(timer);timer=setTimeout(()=>move(Math.round(target)),130)},{passive:false});
track.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();unlockFeedback();const index=e.key==='Home'?0:e.key==='End'?n-1:Math.round(target)+(e.key==='ArrowRight'?1:-1);move(index);buttons[wrapIndex(index,n)].focus({preventScroll:true})});
const resize=()=>paint();window.addEventListener('resize',resize);paint();arcController={track,select(i){unlockFeedback();move(Math.round(position)+(wrapIndex(i-Math.round(position)+n/2,n)-n/2))},destroy(){cancelAnimationFrame(frame);clearTimeout(timer);window.removeEventListener('resize',resize)}}}
function updateArcSelection(track){track.querySelectorAll('.arc-category').forEach(b=>{const active=b.dataset.category===state.category;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1})}
function updateMenuGrid(){const grid=document.querySelector('#menuGrid');if(grid){const list=visibleItems().filter(p=>matchesCategory(p)&&p.name.toLowerCase().includes(state.query.toLowerCase()));grid.innerHTML=list.map(card).join('')||'<p class="no-results">Блюдо не найдено.</p>'}}
function selectArcCategory(button){if(arcController?.track===button.closest('.arc-track'))arcController.select(Number(button.dataset.slot));else{state.category=button.dataset.category;render()}}
const baseRender=render;render=function(){baseRender();attachPromo();attachArc();document.querySelectorAll('.cart-item img,.detail-photo').forEach(img=>{img.src=img.src.replace(/(plov|kazan|roast|shurpa|fatir)\.png$/,'$1-cutout.png')})};render();
